changeSet.sql:
DROP INDEX CONCURRENTLY IF EXISTS idx_feedback_workspace_created;
CREATE INDEX CONCURRENTLY idx_feedback_workspace_created
    ON feedback (workspace_id, created_at DESC, id DESC);

DROP INDEX CONCURRENTLY IF EXISTS idx_agent_job_workspace_created;
CREATE INDEX CONCURRENTLY idx_agent_job_workspace_created
    ON agent_job (workspace_id, created_at DESC, id DESC);

INSERT INTO practice_catalog_installation (workspace_id, installed_at)
SELECT id, CURRENT_TIMESTAMP
FROM workspace;

rollback.sql:
DO $rollback$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM config_audit_event WHERE entity_type = 'PRACTICE_DEFINITION'
    ) THEN
        ALTER TABLE config_audit_event DROP CONSTRAINT ck_config_audit_event_entity_type;
        ALTER TABLE config_audit_event ADD CONSTRAINT ck_config_audit_event_entity_type
            CHECK (entity_type IN (
                'PRACTICE_REVIEW_SETTINGS', 'AGENT_BINDING', 'AGENT_CONFIG', 'AI_CONFIG_BINDING',
                'WORKSPACE_ROLE', 'WORKSPACE_FEATURES', 'WORKSPACE_STATUS',
                'WORKSPACE_TOKEN', 'WORKSPACE_VISIBILITY', 'PRACTICE_ACTIVE',
                'WORKSPACE_INSTANCE_LLM_BUDGET', 'WORKSPACE_OWN_PROVIDER_LLM_BUDGET',
                'WORKSPACE_LLM_BUDGET', 'WORKSPACE_BYO_LLM_BUDGET',
                'WORKSPACE_LLM_CONNECTION', 'WORKSPACE_LLM_MODEL'
            ));
    END IF;
END
$rollback$;

changeSet.sql:
DROP INDEX CONCURRENTLY IF EXISTS idx_agent_job_workspace_purpose_created;
CREATE INDEX CONCURRENTLY idx_agent_job_workspace_purpose_created
    ON agent_job (workspace_id, purpose, created_at DESC, id DESC);
